UPDATE
    dm_approval_template
SET
    template_name = #{item.templateName}
WHERE
    template_identity = #{item.templateIdentity}
    AND
    primary_uid = #{item.primaryUid}
    AND
    approval_type = #{item.approvalType, typeHandler=com.clougence.clouddm.platform.dal.handler.enums.RdpApprovalTypeHandler}
    AND
    template_source = 'PROVIDER'

UPDATE
    dm_approval
SET
    appro_template_name = #{item.templateName}
WHERE
    appro_template_identity = #{item.templateIdentity}
    AND
    primary_uid = #{item.primaryUid}
    AND
    appro_type = #{item.approvalType, typeHandler=com.clougence.clouddm.platform.dal.handler.enums.RdpApprovalTypeHandler}

